from collections import defaultdict

def find_frames(grid, background):
    frame_interiors = {}

    for color in set([r[c] for r in grid for c in range(len(grid[0])) if r[c] != background]):
        pixels = []
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color:
                    pixels.append((r, c))

        if not pixels:
            continue

        r1, c1 = min(r for r, c in pixels), min(c for r, c in pixels)
        r2, c2 = max(r for r, c in pixels), max(c for r, c in pixels)

        height = r2 - r1 + 1
        width = c2 - c1 + 1

        border_ok = True
        for c in range(c1, c2 + 1):
            if grid[r1][c] != color or grid[r2][c] != color:
                border_ok = False
                break
        for r in range(r1, r2 + 1):
            if grid[r][c1] != color or grid[r][c2] != color:
                border_ok = False
                break

        if border_ok and height > 2 and width > 2:
            interior_cells = []
            for r in range(r1 + 1, r2):
                for c in range(c1 + 1, c2):
                    interior_cells.append((r, c))
            frame_interiors[color] = (r1, c1, r2, c2, interior_cells)

    return frame_interiors

